    );

    test(
      'bhv serializationobject 058 a model without unevaluatedProperties false ignores an undeclared key',
      () {
        final category = deserialize(
          '{"id":1,"name":"x","unexpected":true}',
          Category.fromJson,
        );
        expect(category!.name, equals('x'));
      },
    );

