        expect(
          json.containsKey('photoUrls'),
          isTrue,
          reason: 'required field photoUrls present',
        );
        expect(
          json.containsKey('id'),
          isFalse,
          reason: 'optional id left unset must be omitted, not emitted as null',
        );
        expect(
          json.containsKey('category'),
          isFalse,
